"""Offline preview PNG renderer (uses optional vtk + xvfb, assets generated by build_assets.py)."""
import os,sys,numpy as np,trimesh
from pathlib import Path
import vtk
from vtk.util.numpy_support import numpy_to_vtk, numpy_to_vtkIdTypeArray
ROOT=Path(__file__).resolve().parent
scene=trimesh.load(ROOT/'assets/sedan_cabin.glb',force='scene')
renderer=vtk.vtkRenderer()
renderer.GradientBackgroundOn()
renderer.SetBackground(.047,.064,.092)
renderer.SetBackground2(.13,.18,.24)

# physical scene placements from manifest
manifest=__import__('json').loads((ROOT/'assets/asset_manifest.json').read_text())
bag_pos=manifest['driver_airbag_mount']

def draw_mesh(mesh, transform=None, extra=(0,0,0)):
    vertices=np.array(mesh.vertices)
    if transform is not None:
        vv=np.hstack([vertices,np.ones((len(vertices),1))])@np.array(transform).T
        vertices=vv[:,:3]
    vertices+=np.array(extra)
    pts=vtk.vtkPoints();pts.SetData(numpy_to_vtk(vertices,deep=1))
    faces=np.asarray(mesh.faces,dtype=np.int64)
    packed=np.column_stack((np.full(len(faces),3),faces)).ravel()
    polys=vtk.vtkCellArray();polys.SetCells(len(faces),numpy_to_vtkIdTypeArray(packed,deep=1))
    pd=vtk.vtkPolyData();pd.SetPoints(pts);pd.SetPolys(polys)
    normals=vtk.vtkPolyDataNormals();normals.SetInputData(pd);normals.SetFeatureAngle(85);normals.ConsistencyOn();normals.SplittingOff();normals.Update()
    mapper=vtk.vtkPolyDataMapper();mapper.SetInputConnection(normals.GetOutputPort());mapper.ScalarVisibilityOff()
    actor=vtk.vtkActor();actor.SetMapper(mapper)
    c=[.5,.5,.5]
    try:c=list(mesh.visual.material.baseColorFactor[:3]);c=[k/255 for k in c]
    except Exception:pass
    prop=actor.GetProperty();prop.SetColor(*c);prop.SetAmbient(.30);prop.SetDiffuse(.68);prop.SetSpecular(.22);prop.SetSpecularPower(18)
    renderer.AddActor(actor)

for node in scene.graph.nodes_geometry:
    transform,geomname=scene.graph[node]
    draw_mesh(scene.geometry[geomname],transform)
full=trimesh.load(ROOT/'assets/driver_airbag_full.glb',force='mesh')
if '--no-bag' not in sys.argv:
    draw_mesh(full,extra=bag_pos)

# ground faint silhouette
plane=vtk.vtkPlaneSource();plane.SetOrigin(-4,.02,-4);plane.SetPoint1(4,.02,-4);plane.SetPoint2(-4,.02,4)
mapper=vtk.vtkPolyDataMapper();mapper.SetInputConnection(plane.GetOutputPort())
actor=vtk.vtkActor();actor.SetMapper(mapper);actor.GetProperty().SetColor(.13,.18,.23)
renderer.AddActor(actor)

lamp=vtk.vtkLight();lamp.SetPosition(0,3.8,3.2);lamp.SetFocalPoint(0,.7,0);lamp.SetIntensity(.94);renderer.AddLight(lamp)
lamp2=vtk.vtkLight();lamp2.SetPosition(-3,4,-2);lamp2.SetIntensity(.63);renderer.AddLight(lamp2)

window=vtk.vtkRenderWindow();window.SetOffScreenRendering(1);window.SetSize(1400,850);window.AddRenderer(renderer)
cam=renderer.GetActiveCamera(); cam.SetPosition(.22,1.64,.38);cam.SetFocalPoint(-.17,1.12,-1.12);cam.SetViewUp(0,1,0);cam.SetViewAngle(75)
renderer.ResetCameraClippingRange(); window.Render()
flt=vtk.vtkWindowToImageFilter();flt.SetInput(window);flt.SetScale(1);flt.SetInputBufferTypeToRGB();flt.ReadFrontBufferOff();flt.Update()
writer=vtk.vtkPNGWriter();writer.SetFileName(str(ROOT/('preview_no_bag.png' if '--no-bag' in sys.argv else 'preview_deployed.png')));writer.SetInputConnection(flt.GetOutputPort());writer.Write()
print('Rendered',ROOT/'preview.png')
